use vstd::prelude::*;

verus! {
    /// Function to rotate an array to the right by a given amount.
    fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)
        requires
            list.len() > 0, // The input array must be non-empty
        ensures
            new_list.len() == list.len(), // The output array has the same length
            forall(|i: usize| 0 <= i < list.len() ==> new_list[i] == list[(len - (n % len) + i) % len]), // The elements are correctly rotated
    {
        let len = list.len();
        let s = len - (n % len); // Calculate the starting index for the suffix

        // Create a new vector to hold the rotated values
        let mut new_list: Vec<u32> = Vec::new();
        new_list.reserve(len); // Reserve space for the new list

        // Append the suffix from index s to the end of the original list
        for i in s..len {
            new_list.push(list[i]);
        }

        // Append the prefix from index 0 to s
        for i in 0..s {
            new_list.push(list[i]);
        }

        new_list // Return the new rotated list
    }
}
